  "items:ring_master_attack:name": "剑术大师之戒",
  "items:ring_master_completion:description": "唯有精通全部二十一项技艺者方可佩戴。一枚静默的金环，是授予之物，从不贩售。",
  "items:ring_master_hunting:name": "猎人陷阱戒指",
  "items:ring_master_hunting:description": "被千次布设与触发的陷阱磨得光滑。有 5% 概率获得双倍猎物。",
  "items:ring_master_completion:name": "圆满之戒",
  "items:ring_master_cooking:description": "沾染过它监督过的每一道菜肴。佩戴此物烹饪，菜肴永不失败。",
  "items:ring_master_cooking:name": "灵魂厨师之戒",
  "items:ring_master_defence:description": "曾挡开足以击倒寻常守卫的攻击。赋予2%格挡几率。",
  "items:ring_master_defence:name": "壁垒之戒",
  "items:ring_master_farming:description": "散发着翻耕泥土与耐心时节的气息。佩戴此物时，作物成熟速度加快8%。",
  "items:ring_master_farming:name": "掘墓园丁之戒",
  "items:ring_master_fishing:description": "隐约散发着深水与更古老之物的气息。5%几率钓获双倍渔获。",
  "items:ring_master_fishing:name": "虚空垂钓者之戒",
  "items:ring_master_foraging:description": "镶嵌着它拂过的每一片叶子的碎屑。5%几率采得双倍收获。",
  "items:ring_master_foraging:name": "荒野采集者之戒",
  "items:ring_master_herblore:description": "浸泡在苦涩烟雾中的时日久远得超出记忆。佩戴此物时，药水与药剂效果延长10%。",
  "items:ring_master_herblore:name": "毒药调制师之戒",
  "items:ring_master_jewelcrafting:description": "如千颗未镶嵌的宝石般摄住光芒。5%几率切磨出双倍宝石。",
  "items:ring_master_jewelcrafting:name": "宝石匠师之戒",
  "items:ring_master_leatherworking:description": "由从不浪费的大师雕琢而成。5%几率使工艺节省材料。",
  "items:ring_master_leatherworking:name": "制革大师之戒",
  "items:ring_master_magic:description": "以千道破碎护盾的余痕锻成。赋予3%护盾破除。",
  "items:ring_master_magic:name": "大法师之戒",
  "items:ring_master_mining:description": "锻造于最深的矿脉之中，铭记着它触碰过的每一道矿脉。5%几率凿获双倍矿石。",
  "items:ring_master_mining:name": "深渊破裂者之戒",
  "items:ring_master_power:description": "承载着军阀每一记致命终结之力。赋予3%暴击伤害。",
  "items:ring_master_power:name": "军阀之戒",
  "items:ring_master_ranged:description": "磨砺目光，直至任何闪避都显得不够迅捷。赋予2%精准。",
  "items:ring_master_ranged:name": "鹰眼之戒",
  "items:ring_master_runecrafting:description": "隐隐嗡鸣着被束缚的奥秘符文。5%几率缚结双倍符文。",
  "items:ring_master_runecrafting:name": "符文缚结者之戒",
  "items:ring_master_slayer:description": "刻满千份契约的记录。可多获得10%的猎手点数。",
  "items:ring_master_slayer:name": "赏金大师之戒",
  "items:ring_master_smithing:description": "历经千炉炙烤，却从未熔毁。5%几率使锻炉节省材料。",
  "items:ring_master_smithing:name": "锻炉大师之戒",
