  "items:slayer_amulet:description": "一枚镶有虚空使者碎片的水晶护符。散发着冰冷、精准的力量，惠及一切战斗风格。",
  "items:slayer_amulet:name": "猎魔护符",
  "items:slayer_combat_draught:description": "由猎魔塔精华蒸馏而成。加快你的打击（攻击间隔 -450ms），并磨砺你的准头（暴击 +8%），持续 10 分钟。",
  "items:slayer_combat_draught:name": "猎魔者战斗药剂",
  "items:slayer_greaves:description": "以惧牙兽牙齿的破碎残片强化的胫甲。为高于你身份的猎物而造：对战斗等级高于你的怪物造成 +20% 伤害。",
  "items:slayer_greaves:name": "猎魔胫甲",
  "items:slayer_helm:description": "以猎魔塔最凶恶恐怖之物的精华锻成的杰作头盔，标记着佩戴者的委托：对当前任务目标造成 +20% 伤害，佩戴时无需任何结界物品即可抵御塔层的一切威胁。",
  "items:slayer_helm:name": "猎魔头盔",
  "items:slayer_hunters_cape:description": "一件磨损的披风，由布伦娜颁发给已完成首三十份契约的猎人。每场狩猎的开场一击威力最猛：对未受伤的目标造成 +15% 伤害。",
  "items:slayer_hunters_cape:name": "猎人披风",
  "items:slayer_hunters_elixir:description": "专供资深猎魔者。加快你的攻击（间隔 -600ms），暴击 +12%，暴击伤害 +20%，持续 30 分钟。相较战斗药剂拥有更优的持续续航。",
  "items:slayer_hunters_elixir:name": "猎魔者猎人灵药",
  "items:slayer_vambraces:description": "以烧焦的余烬可怜虫兽皮与硬化塔层皮革制成的臂甲。狩猎中的每次击杀都能愈合猎人的伤口：每次击杀 +4 点生命。",
  "items:slayer_vambraces:name": "猎魔臂甲",
  "items:slayer_war_brew:description": "一份古老猎魔宗师的配方。大幅加快你的攻击（间隔 -750ms），暴击 +20%，暴击伤害 +30%，持续 60 分钟。专为最伟大的狩猎保留。",
  "items:slayer_war_brew:name": "猎魔者战争药剂",
  "items:slayer_ward_capsule:description": "一只密封容器，内含全部四种塔层结界组件，熔合为单一的防护核心。",
