  "quests:q_ash_hunter:description": "在灰烬原猎杀 20 只灰烬鼠：边域昔日粮仓的残余，不该也落入这些害兽之口。",
  "quests:q_ash_hunter:name": "灰原灭虫者",
  "quests:q_blackthorn_1:description": "击倒 20 只从黑荆棘林灌木丛中挣脱而出的根须怪，森林已学会自卫。",
  "quests:q_blackthorn_1:name": "深入黑荆棘林",
  "quests:q_blackthorn_2:description": "深入黑荆棘林，直抵树根下的古冢，击败 25 只扭曲根须怪。",
  "quests:q_blackthorn_2:name": "扭曲的深处",
  "quests:q_boar_hunter:description": "在牧野斩杀 15 头野猪。没了栅栏与牧人，它们养成了自己的习性，余烬堡需要它们的兽皮。",
  "quests:q_boar_hunter:name": "狂野狩猎",
  "quests:q_crypt_1:description": "进入墓穴，斩杀 10 名骷髅战士。护墓者团曾将他们封印于此；如今封印已非处处牢固。",
  "quests:q_crypt_1:name": "陨落者之骨",
  "quests:q_crypt_2:description": "墓穴的下层厅堂由骷髅矛兵把守，这支驻军早已不再索取俸禄。砍倒其中 20 名。",
  "quests:q_crypt_2:name": "不屈之死者",
  "quests:q_crypt_3:description": "骷髅冰霜法师盘踞在墓穴最深的地窖。趁它们尚未将你冻僵，摧毁 10 名。",
  "quests:q_crypt_3:name": "冰封寂静",
  "quests:q_dire_wolf_hunt:description": "恐狼在荒林深处潜行，体型远超寻常狼群。斩杀 15 只这般凶猛的掠食者。",
  "quests:q_dire_wolf_hunt:name": "荒野之恐",
  "quests:q_fighter_1:description": "累计击败 75 名敌人。血与汗铸就余烬堡所需的斗士。",
  "quests:q_fighter_1:name": "老练斗士",
  "quests:q_fighter_2:description": "累计砍倒 200 名敌人。仆从们已开始记住你的名字。",
  "quests:q_fighter_2:name": "坚毅战士",
  "quests:q_fighter_3:description": "累计击败 500 名敌人。每一个倒下的敌人，都是灰烬永远无法收录的一笔。",
  "quests:q_fighter_3:name": "百战老兵",
  "quests:q_first_blood:description": "在边境之地斩杀 10 只哥布林，它们劫掠余烬堡附近最后的农场已经够久了。",
  "quests:q_first_blood:name": "哥布林之血",
  "quests:q_first_steps:description": "在余烬堡门外的牧野猎杀 5 只小鸡：不过是初次持械，仅此而已。",
  "quests:q_first_steps:name": "初出茅庐",
  "quests:q_frost_hound:description": "霜猎犬盘踞于冰霜洞窟，那是矿坑掘得过深、触及虚空之寒的地方。猎杀其中 15 只。",
  "quests:q_frost_hound:name": "寒冷狩猎",
  "quests:q_gatherer:description": "为余烬堡收集 50 件任意物品：伐木、采矿、采药或搜刮怪物。",
  "quests:q_gatherer:name": "采集者",
  "quests:q_gatherer_2:description": "为余烬堡累计采集 5,000 件物品。这片土地仅将所剩无几的馈赠，留给坚持不懈之人。",
  "quests:q_gatherer_2:name": "不懈的采集者",
  "quests:q_goblin_slayer:description": "进一步击退哥布林部族：在边境之地斩杀 30 只哥布林，它们的领地曾是边域的盾墙。",
  "quests:q_goblin_slayer:name": "哥布林猎手",
  "quests:q_miner_1:description": "将采矿提升至 5 级，为余烬堡的熔炉开辟更好的矿脉。",
  "quests:q_miner_1:name": "镐与石",
  "quests:q_miner_2:description": "将采矿提升至 30 级。边境之地更深的矿脉需要更强壮的臂膀。",
  "quests:q_miner_2:name": "钢铁意志",
  "quests:q_miner_3:description": "将采矿提升至 50 级。边域最稀有的矿石深埋于地表之下，比以往任何时候都更深。",
  "quests:q_miner_3:name": "深土召唤",
  "quests:q_moss_golem_hunt:description": "苔藓魔像已占据森林空地，如今连森林也需要守卫了。击碎其中 15 个。",
  "quests:q_moss_golem_hunt:name": "苔藓之患",
  "quests:q_roc_fledgling:description": "雏鹏统治着高地的热气流，那里的天空依旧澄澈。击落 10 只这般巨大的飞鸟。",
  "quests:q_roc_fledgling:name": "高地天望",
  "quests:q_shaman_hunt:description": "哥布林萨满从古老的警戒篝火中汲取黯淡精华，煽动部族走向战争。让其中 10 名噤声。",
  "quests:q_shaman_hunt:name": "萨满狩猎",
  "quests:q_skiller_1:description": "使所有技能的合计总等级达到 20，余烬堡视每一双能干的手为双倍之力。",
  "quests:q_skiller_1:name": "万事通",
  "quests:q_skiller_2:description": "使合计总等级达到 50。只精一门手艺的人，在这个世界撑不了多久。",
  "quests:q_skiller_2:name": "多才冒险者",
  "quests:q_skiller_3:description": "使合计总等级达到 75。诸多道路已引你至此，余烬堡一条也不曾遗忘。",
  "quests:q_skiller_3:name": "老练冒险者",
  "quests:q_skiller_4:description": "使合计总等级达到 100。从余烬堡出发之人，少有走得这般远的。",
  "quests:q_skiller_4:name": "精通之路",
  "quests:q_skiller_5:description": "使合计总等级达到 150。你的事迹如今在余烬堡的炉火旁被传颂，一如昔日炉心传奇，边域所有技艺曾在那里熬过了世界的陷落。",
  "quests:q_skiller_5:name": "炉心传奇",
  "quests:q_slagpit_1:description": "闯入熔渣坑，那里曾熔铸神铁，消灭 20 只潜伏于阴影中的深坑蜘蛛。",
  "quests:q_slagpit_1:name": "深入坑窟",
  "quests:q_slagpit_2:description": "钢铁亡魂巡视着最深的通道，他们是死在铠甲中的铁匠，从未被告知可以卸任。击倒 10 具这般不死的构造体。",
  "quests:q_slagpit_2:name": "钢铁作祟",
  "quests:q_smith_journeyman:description": "将锻造提升至 20 级。余烬堡的熔炉奖赏耐心：在挑战更硬的金属前，先掌握基础。",
  "quests:q_smith_journeyman:name": "熟手铁匠",
  "quests:q_smith_master:description": "将锻造提升至 50 级。唯有真正专注者，方能锻造边域最稀有的金属：神铁不会宽恕急躁。",
  "quests:q_smith_master:name": "熔炉大师",
  "quests:q_stag_hunter:description": "宛如丰碑的野生雄鹿称霸荒林狩猎场。击倒 20 头这般骄傲的野兽。",
  "quests:q_stag_hunter:name": "林中之王",
  "quests:q_thorn_wolf_pack:description": "黑荆棘林的荆棘狼比它们的同类更危险，森林磨砺了它们。斩杀其中 20 只。",
  "quests:q_thorn_wolf_pack:name": "荆棘狼群",
  "quests:q_wolf_slayer:description": "在荒林狩猎场猎杀 15 只灰狼，自从无人再狩猎，这里的一切都长得更大了。",
  "quests:q_wolf_slayer:name": "深入荒林",
  "quests:q_woodcutter_1:description": "将伐木提升至 5 级。一把利斧、一颗坚毅之心，便已足够，余烬堡别无所求。",
  "quests:q_woodcutter_1:name": "深入林地",
  "quests:q_woodcutter_2:description": "将伐木提升至 15 级，以砍伐橡树：营地需要的不只是细柴。",
  "quests:q_woodcutter_2:name": "老练伐木工",
  "quests:q_woodcutter_3:description": "将伐木提升至 30 级。古老的林苑只向配得上的人吐露秘密，黑荆棘林偏爱敬重，而非急躁。",
  "quests:q_woodcutter_3:name": "巨斧大师",
